// import File and Paths from expo
import { File, Paths } from 'expo-file-system';

import { Ingredient } from 'data/recipe/ingredient';
import { Recipe } from 'data/recipe/recipe';

const recipeFile = new File(Paths.document, 'recipes.json');
const ingredientFile = new File(Paths.document, 'ingredients.json');

// Read a JSON array from a file; return [] if missing or unreadable
function readList(file) {
  if (!file.exists) return [];

  try {
    const data = JSON.parse(file.textSync());
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

function writeList(file, list) {
  if (!file.exists) file.create();
  file.writeSync(JSON.stringify(list, null, 2));
}

// Replace the entry that matches, or add it if none does
function upsert(list, entry, matches) {
  const index = list.findIndex(matches);
  if (index === -1) list.push(entry);
  else list[index] = entry;
  return list;
}

// Turn saved entries back into objects, skipping any that are invalid
function hydrate(list, build) {
  return list.flatMap((entry) => {
    try {
      return [build(entry)];
    } catch {
      return [];
    }
  });
}

function toIngredient(name, data) {
  return new Ingredient(name, data.quantity, data.type);
}

function toRecipe(entry) {
  const [name, data] = Object.entries(entry)[0]; // { [name]: { ...ingredients } }
  const ingredients = Object.entries(data).map(([key, value]) => toIngredient(key, value));
  return new Recipe(name, ingredients);
}

//Recipes
export function loadRecipe() {
  return hydrate(readList(recipeFile), toRecipe);
}

export function saveRecipe(item) {
  const name = item.getName();
  const entry = JSON.parse(item.getJSON()); // { [name]: { ...ingredients } }
  writeList(recipeFile, upsert(readList(recipeFile), entry, (r) => name in r));
}

export function deleteRecipe(name) {
  writeList(recipeFile, readList(recipeFile).filter((r) => Object.keys(r)[0] !== name));
}

//Ingredient
export function loadIngredient() {
  return hydrate(readList(ingredientFile), ({ name, ...data }) => toIngredient(name, data));
}

export function saveIngredient(item) {
  const name = item.getName();
  const entry = { name, ...item.getData() }; // getData() leaves out the name
  writeList(ingredientFile, upsert(readList(ingredientFile), entry, (i) => i.name === name));
}

export function deleteIngredient(name) {
  writeList(ingredientFile, readList(ingredientFile).filter((i) => i.name !== name));
}